import{_ as e,o as a,c as r,ah as o}from"./chunks/framework.CRsDMGp2.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"src/en/guide/introduction.md"}'),n={name:"en/guide/introduction.md"};function i(s,t,d,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Naia is <strong>edPage group</strong>&#39;s project management platform: tracking phases and milestones, documents and deliverables, electronic signatures, invoicing and online payment, and built-in messaging, for everyone involved in a project — clients, internal team, external partners and referrers.</p><p>This guide is organized by role: each profile only has access to what concerns it, so each page covers exactly what you&#39;ll see in your own space.</p><h2 id="roles-on-naia" tabindex="-1">Roles on Naia <a class="header-anchor" href="#roles-on-naia" aria-label="Permalink to &quot;Roles on Naia&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>What they do on Naia</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Client</strong></td><td>Tracks their project&#39;s progress, approves deliverables, pays invoices</td><td><a href="./client.html">Client guide</a></td></tr><tr><td><strong>Partner</strong></td><td>Carries out tasks assigned by a project manager, submits invoices</td><td><a href="./partenaire.html">Partner guide</a></td></tr><tr><td><strong>Referrer</strong></td><td>Tracks the portfolio of clients they&#39;ve referred and their commissions</td><td><a href="./apporteur-affaires.html">Referrer guide</a></td></tr><tr><td><strong>Project manager</strong></td><td>Runs one or more projects end to end</td><td><a href="./chef-projet-collaborateurs.html">Project manager &amp; Collaborators guide</a></td></tr><tr><td><strong>Collaborator</strong></td><td>Carries out technical work (development, consulting, cybersecurity…)</td><td><a href="./chef-projet-collaborateurs.html">Project manager &amp; Collaborators guide</a></td></tr><tr><td><strong>Administrator</strong></td><td>Manages accounts, billing and platform security</td><td><a href="./administrateur.html">Administrator guide</a></td></tr><tr><td><strong>Direction</strong></td><td>Views a read-only overview of the whole activity</td><td><a href="./direction.html">Direction guide</a></td></tr></tbody></table><p>An account only ever has one role at a time — permissions and dashboard content adapt automatically.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Naia is invite-only: there&#39;s no self-service registration. You receive an invitation email with a link to activate your account and choose your password. Once your account is activated, sign in from the login page with your email address and that password.</p><p>If you haven&#39;t received an invitation but should have access to a project, contact whoever should have invited you (your project manager, or your referrer if you&#39;re a client) — see also the <a href="./support.html">Need help?</a> page.</p><h2 id="account-security" tabindex="-1">Account security <a class="header-anchor" href="#account-security" aria-label="Permalink to &quot;Account security&quot;">​</a></h2><p>From <strong>Settings &gt; Security</strong>, you can:</p><ul><li>change your password;</li><li>enable two-factor authentication (2FA), strongly recommended and automatically suggested to administrators when they sign in.</li></ul><h2 id="notifications-and-messaging" tabindex="-1">Notifications and messaging <a class="header-anchor" href="#notifications-and-messaging" aria-label="Permalink to &quot;Notifications and messaging&quot;">​</a></h2><p>You&#39;re notified automatically (bell icon at the top of the screen) at the key steps that concern you: milestone reached, deliverable submitted, document awaiting your approval, invoice due, delay reported. Every project also has built-in messaging to talk with the other people involved without leaving the platform.</p><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><p>Naia is available in French and English. The language switcher sits in the top-right corner of the screen, on every page.</p>',16)])])}const p=e(n,[["render",i]]);export{g as __pageData,p as default};
